/// Candidate event types retained for backend validation.
enum TelemetryEventType {
  harshAccelerationCandidate,
  harshBrakingCandidate,
  swervingCandidate,
  abruptLaneChangeCandidate,
  speedingCandidate,
  wrongWayCandidate,
  signalizedIntersectionCrossingCandidate,
  phoneMovement,
  gpsQualityLoss,
}

/// Compact event summary generated by the recorder.
class TelemetryEventCandidate {
  /// Creates an event candidate.
  const TelemetryEventCandidate({
    required this.id,
    required this.type,
    required this.startedAtMillis,
    required this.endedAtMillis,
    required this.confidence,
    required this.minimumValue,
    required this.maximumValue,
    required this.meanValue,
    this.speedBeforeMps,
    this.speedAfterMps,
    this.latitude,
    this.longitude,
    this.effectiveSpeedLimitKph,
    this.evidenceChunkId,
    this.metadata = const <String, Object?>{},
  });

  /// Candidate identifier.
  final String id;

  /// Candidate category.
  final TelemetryEventType type;

  /// Candidate start timestamp.
  final int startedAtMillis;

  /// Candidate end timestamp.
  final int endedAtMillis;

  /// Detection confidence from 0 to 1.
  final double confidence;

  /// Minimum measured value.
  final double minimumValue;

  /// Maximum measured value.
  final double maximumValue;

  /// Mean measured value.
  final double meanValue;

  /// Speed before the event.
  final double? speedBeforeMps;

  /// Speed after the event.
  final double? speedAfterMps;

  /// Event latitude.
  final double? latitude;

  /// Event longitude.
  final double? longitude;

  /// Effective legal limit when available.
  final double? effectiveSpeedLimitKph;

  /// Identifier of the raw evidence chunk.
  final String? evidenceChunkId;

  /// Additional compact metadata.
  final Map<String, Object?> metadata;

  /// Event duration.
  int get durationMillis => endedAtMillis - startedAtMillis;

  /// Returns a copy with an evidence identifier.
  TelemetryEventCandidate withEvidenceChunkId(String value) {
    return TelemetryEventCandidate(
      id: id,
      type: type,
      startedAtMillis: startedAtMillis,
      endedAtMillis: endedAtMillis,
      confidence: confidence,
      minimumValue: minimumValue,
      maximumValue: maximumValue,
      meanValue: meanValue,
      speedBeforeMps: speedBeforeMps,
      speedAfterMps: speedAfterMps,
      latitude: latitude,
      longitude: longitude,
      effectiveSpeedLimitKph: effectiveSpeedLimitKph,
      evidenceChunkId: value,
      metadata: metadata,
    );
  }

  /// JSON representation.
  Map<String, Object?> toJson() => <String, Object?>{
        'id': id,
        'type': type.name,
        'startedAtMillis': startedAtMillis,
        'endedAtMillis': endedAtMillis,
        'confidence': confidence,
        'minimumValue': minimumValue,
        'maximumValue': maximumValue,
        'meanValue': meanValue,
        'speedBeforeMps': speedBeforeMps,
        'speedAfterMps': speedAfterMps,
        'latitude': latitude,
        'longitude': longitude,
        'effectiveSpeedLimitKph': effectiveSpeedLimitKph,
        'evidenceChunkId': evidenceChunkId,
        'metadata': metadata,
      };
}
